function reviewCell(row: T.PrSnapshot): string {
  if (row.kind !== "open") return "\u2014";
  const open = row.threads.length;
  if (row.reviewAutomationRunning)
    return open ? `🤖 running, ${open} open` : "🤖 running";
  if (open) return `📝 ${open} open`;
  switch (row.facts.reviewDecision) {
    case "APPROVED":
      return "✅ approved";
    case "CHANGES_REQUESTED":
      return "⚠️ changes requested";
    case "REVIEW_REQUIRED":
      return "⏳ review required";
    case null:
      return "— no decision";
    default: {
      const exhaustive: never = row.facts.reviewDecision;
      return exhaustive;
    }
  }
}

